for(const [name,meaning] of Object.entries(operationDescriptions))commandInfo[name]??=[meaning,{}];
const explicitFlags={uname:{'-r':'只显示内核发布版本'},date:{'-Iseconds':'ISO 8601 时间输出，精确到秒'},stat:{},readlink:{'-f':'解析并规范化路径中的链接'},namei:{'-l':'逐级展示详细权限与属主'},df:{'-i':'查看 inode 数量与使用率'},lsblk:{'-f':'显示文件系统类型、标识和挂载点'},lsof:{'+L1':'选择链接数小于 1 的已打开文件'},pgrep:{'-a':'显示完整命令行','-f':'用完整命令行匹配'},top:{'-b':'批处理输出','-n':'后面的数字是显示次数'},free:{'-h':'易读内存单位'},iostat:{'-x':'扩展磁盘统计','-z':'不显示没有活动的设备'},pidstat:{'-p':'后面指定进程编号'},ip:{'-br':'简短格式'},traceroute:{'-n':'不把地址解析为名字','-m':'后面的数值是最大跳数'},tracepath:{'-n':'使用数字地址'},mtr:{'-n':'数字地址','-r':'报告模式','-c':'后面的数字是探测轮数'},dig:{'+short':'只显示简要答案'},curl:{'--connect-timeout':'后面是连接阶段超时秒数','--max-time':'后面是整个操作最长秒数'},nc:{'-v':'详细结果','-z':'扫描监听而不发送业务数据','-w':'后面是超时秒数'},openssl:{'-connect':'后面是主机与端口','-servername':'后面是 SNI 主机名','-brief':'简短握手信息'},tcpdump:{'-n':'不解析名称','-i':'后面是网卡名','-c':'后面是最大抓包数'},'firewall-cmd':{'--state':'查询服务是否运行','--get-active-zones':'查询活动区域与绑定接口','--zone=public':'选择 public 区域','--list-all':'列出区域主要配置','--permanent':'查看或修改持久配置；本课只读','--list-ports':'仅列明确端口项，不包含 services 隐含端口'},ufw:{},iptables:{'-S':'以规则规格列出策略'},systemctl:{'--type=service':'只看服务类型单元','--state=failed':'只看失败状态','--all':'包含非活动单元'},dmesg:{'--level=err,warn':'只显示错误与警告'},crontab:{'-l':'列当前用户计划任务'},ssh:{'-G':'输出解析后的配置，不建立连接'},rsync:{'-a':'归档模式','-v':'显示详细信息','-n':'演练，不实际复制'},tar:{'-t':'列归档成员','-f':'后面是归档文件路径'}};
for(const [cmd,flags] of Object.entries(explicitFlags))Object.assign(commandInfo[cmd][1],flags);
const operationBaseDescribe=describeToken;
describeToken=function(token,cmd,index){const known=operationBaseDescribe(token,cmd,index);if(known)return known;return linuxTokenNotes.get(cmd+':'+token)||null;};
function operationSignature(raw){const ts=coachTokens(raw);if(ts.includes('|'))return null;const cmd=ts.shift(),flags=[],args=[],takes={traceroute:['-m'],mtr:['-c'],nc:['-w'],tcpdump:['-i','-c'],top:['-n'],pidstat:['-p'],journalctl:['-u','-n'],tar:['-f'],curl:['--connect-timeout','--max-time'],openssl:['-connect','-servername']};for(let i=0;i<ts.length;i++){const t=ts[i];if(t.startsWith('-')){const expanded=/^-[A-Za-z]{2,}$/.test(t)&&['ss','mtr','nc','tcpdump','rsync','tar','iostat'].includes(cmd)?[...t.slice(1)].map(ch=>'-'+ch):[t];for(const flag of expanded){if(takes[cmd]?.includes(flag)){if(ts[i+1]===undefined)return null;flags.push(flag+'='+ts[++i]);}else flags.push(flag);}}else args.push(t);}return JSON.stringify({cmd,args,flags:flags.sort()});}
const operationBaseRun=JobEngine.prototype.jobRun;
JobEngine.prototype.jobRun=function(command,input){if(input===undefined&&!command.includes('|')){const sig=operationSignature(command);const entry=operationsCatalog.find(row=>operationSignature(row[1])===sig);if(entry)return entry[2];}return operationBaseRun.call(this,command,input);};
const operationBaseEquivalent=commandEquivalent;
commandEquivalent=function(value,target,job){if(operationBaseEquivalent(value,target,job))return true;return operationsCatalog.some(row=>row[1]===target)&&operationSignature(value)===operationSignature(target);};
